   123  void av1_alloc_cdef_buffers(AV1_COMMON *const cm,
   124                              AV1CdefWorkerData **cdef_worker,
   125                              AV1CdefSync *cdef_sync, int num_workers) {
   126    const int num_planes = av1_num_planes(cm);
   127    const int luma_stride =
   128        ALIGN_POWER_OF_TWO(cm->mi_params.mi_cols << MI_SIZE_LOG2, 4);
   129    CdefInfo *cdef_info = &cm->cdef_info;
   130    AV1CdefRowSync **cdef_row_mt = &cdef_sync->cdef_row_mt;
   131    // Check for configuration change
   132    const int is_sub_sampling_changed =
   133        (cdef_info->allocated_subsampling_x != cm->seq_params.subsampling_x ||
   134         cdef_info->allocated_subsampling_y != cm->seq_params.subsampling_y);
   135    const int is_frame_scaled =
   136        cdef_info->allocated_mi_cols != cm->mi_params.mi_cols;
   137    const int is_cdef_flag_changed =
   138        cdef_info->prev_cdef_enable_flag != cm->seq_params.enable_cdef;
   139    const int is_large_scale_tile_changed =
   140        cdef_info->prev_large_scale_tile_flag != cm->tiles.large_scale;
   141    const int is_num_planes_changed = cdef_info->prev_num_planes != num_planes;
   142    const int num_mi_rows =
   143        (cm->mi_params.mi_rows + MI_SIZE_64X64 - 1) / MI_SIZE_64X64;
   144    const int is_num_workers_changed =
   145        cdef_info->allocated_num_workers != num_workers;
   146    // num-bufs=3 represents ping-pong buffers for top linebuf,
   147    // followed by bottom linebuf.
   148    // ping-pong is to avoid top linebuf over-write by consecutive row.
   149    int num_bufs = 3;
   150    if (num_workers > 1)
   151      num_bufs = (cm->mi_params.mi_rows + MI_SIZE_64X64 - 1) / MI_SIZE_64X64;
   152
   153    // TODO(vishnu): Simplify the below conditional logic based on linebuf_size.
   154    if (is_frame_scaled || is_sub_sampling_changed || is_cdef_flag_changed ||
   155        is_large_scale_tile_changed || is_num_planes_changed ||
   156        is_num_workers_changed)
   157      av1_free_cdef_buffers(cm, cdef_worker, cdef_sync,
   158                            cdef_info->allocated_num_workers);
   159
   160    // Store configuration to check change in configuration
   161    cdef_info->allocated_mi_cols = cm->mi_params.mi_cols;
   162    cdef_info->allocated_mi_rows = num_mi_rows;
   163    cdef_info->allocated_subsampling_x = cm->seq_params.subsampling_x;
   164    cdef_info->allocated_subsampling_y = cm->seq_params.subsampling_y;
   165    cdef_info->prev_cdef_enable_flag = cm->seq_params.enable_cdef;
   166    cdef_info->prev_large_scale_tile_flag = cm->tiles.large_scale;
   167    cdef_info->prev_num_planes = num_planes;
   168    cdef_info->allocated_num_workers = num_workers;
   169
   170    if (!cm->seq_params.enable_cdef && cm->tiles.large_scale) return;
   171
   172    for (int plane = 0; plane < num_planes; plane++) {
   173      if (cdef_info->linebuf[plane] == NULL) {
   174        const int stride =
   175            luma_stride >>
   176            (plane == AOM_PLANE_Y ? 0 : cm->seq_params.subsampling_x);
   177        CHECK_MEM_ERROR(cm, cdef_info->linebuf[plane],
   178                        aom_malloc(sizeof(*cdef_info->linebuf) * num_bufs *
   179                                   (CDEF_VBORDER << 1) * stride));
   180      }
   181    }
   182
   183    // Memory allocation of column buffer & source buffer (worker_0).
   184    alloc_cdef_bufs(cm, cdef_info->colbuf, &cdef_info->srcbuf, num_planes);
   185
   186    if (num_workers < 2) return;
   187
   188    if (*cdef_worker == NULL)
   189      CHECK_MEM_ERROR(cm, *cdef_worker,
   190                      aom_calloc(num_workers, sizeof(**cdef_worker)));
   191
   192    for (int idx = num_workers - 1; idx >= 1; idx--) {
   193      // Memory allocation of column buffer & source buffer for remaining workers.
   194      alloc_cdef_bufs(cm, (*cdef_worker)[idx].colbuf, &(*cdef_worker)[idx].srcbuf,
   195                      num_planes);
   196    }
   197
   198    if (*cdef_row_mt == NULL) {
   199      CHECK_MEM_ERROR(cm, *cdef_row_mt,
   200                      aom_malloc(sizeof(**cdef_row_mt) * num_mi_rows));
   201  #if CONFIG_MULTITHREAD
   202      for (int row_idx = 0; row_idx < num_mi_rows; row_idx++) {
   203        CHECK_MEM_ERROR(cm, (*cdef_row_mt)[row_idx].row_mutex_,
   204                        aom_malloc(sizeof(*(*cdef_row_mt)[row_idx].row_mutex_)));
   205        pthread_mutex_init((*cdef_row_mt)[row_idx].row_mutex_, NULL);
   206
   207        CHECK_MEM_ERROR(cm, (*cdef_row_mt)[row_idx].row_cond_,
   208                        aom_malloc(sizeof(*(*cdef_row_mt)[row_idx].row_cond_)));
   209        pthread_cond_init((*cdef_row_mt)[row_idx].row_cond_, NULL);
   210
   211        (*cdef_row_mt)[row_idx].is_row_done = 0;
   212      }
   213  #endif  // CONFIG_MULTITHREAD
   214    }
   215  }
